package cn.usage.builder;

import cn.core.ex.HandlingException;
import cn.core.in.BufferedImageSource;
import cn.core.in.InputStreamImageSource;
import cn.usage.TestUtils;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.List;
import javax.imageio.ImageIO;

public class ImageSourceBuilderTest {

    @Test
    public void testObtainSourceImagesWithOriginalFormat() {
        try {
            // Construct the correct path to the test images
            String nothingImagePath = "test/resources/nothing.jpg";
            String frameImagePath = "test/resources/frame.jpg";

            InputStream nothingStream = ImageSourceBuilderTest.class.getResourceAsStream(nothingImagePath);
            InputStream frameStream = ImageSourceBuilderTest.class.getResourceAsStream(frameImagePath);

            if (nothingStream == null || frameStream == null) {
                throw new RuntimeException("Test images not found in resources.");
            }

            BufferedImageSource<InputStream> nothingSource = new InputStreamImageSource(nothingStream);
            BufferedImageSource<InputStream> frameSource = new InputStreamImageSource(frameStream);

            List<BufferedImageSource<InputStream>> sourcesList = new ArrayList<>();
            sourcesList.add(nothingSource);
            sourcesList.add(frameSource);

            // Create ImageSourceBuilder with sources and useOriginalFormat
            ImageSourceBuilder<InputStream> builder = new ImageSourceBuilder<>(sourcesList)
                    .useOriginalFormat();

            // Obtain source images
            List<BufferedImage> sourceImages = builder.obtainSourceImages();

            // Verify the results
            Assert.assertEquals(2, sourceImages.size());

            // Read expected images
            BufferedImage expectedNothing = ImageIO.read(ImageSourceBuilderTest.class.getResourceAsStream(nothingImagePath));
            BufferedImage expectedFrame = ImageIO.read(ImageSourceBuilderTest.class.getResourceAsStream(frameImagePath));

            // Verify first image matches 'nothing.jpg'
            Assert.assertTrue(compareImages(sourceImages.get(0), expectedNothing));

            // Verify second image matches 'frame.jpg'
            Assert.assertTrue(compareImages(sourceImages.get(1), expectedFrame));

            // Verify format name is set to 'JPEG'
            String formatName = getFormatName(builder);
            Assert.assertEquals("JPEG", formatName);

        } catch (IOException e) {
            throw new RuntimeException("Error reading test images", e);
        }
    }

    private boolean compareImages(BufferedImage img1, BufferedImage img2) {
        if (img1.getWidth() != img2.getWidth() || img1.getHeight() != img2.getHeight()) {
            return false;
        }
        for (int y = 0; y < img1.getHeight(); y++) {
            for (int x = 0; x < img1.getWidth(); x++) {
                if (img1.getRGB(x, y) != img2.getRGB(x, y)) {
                    return false;
                }
            }
        }
        return true;
    }

    private String getFormatName(ImageSourceBuilder<InputStream> builder) {
        try {
            java.lang.reflect.Field field = ImageSourceBuilder.class.getDeclaredField("formatName");
            field.setAccessible(true);
            return (String) field.get(builder);
        } catch (NoSuchFieldException | IllegalAccessException e) {
            throw new RuntimeException("Error accessing formatName", e);
        }
    }
}

