import java.util.Arrays;
import java.util.List;
import java.text.MessageFormat;
import cn.core.utils.StringUtils;

public class ImageSourceBuilderTest {

    @Test
    public void testEx_obtainSourceImages_multipleFormats() {
        // Create two BufferedImageSource with different formats
        List<BufferedImageSource<BufferedImage>> sources = new ArrayList<>();
        BufferedImage jpgImage = new BufferedImage(100, 100, BufferedImage.TYPE_INT_RGB);
        BufferedImage bmpImage = new BufferedImage(100, 100, BufferedImage.TYPE_INT_RGB);

        // Create custom sources with specified formats
        CustomBufferedImageSource jpgSource = new CustomBufferedImageSource(jpgImage);
        jpgSource.setOriginalFormatName("jpg");
        CustomBufferedImageSource bmpSource = new CustomBufferedImageSource(bmpImage);
        bmpSource.setOriginalFormatName("bmp");

        sources.add(jpgSource);
        sources.add(bmpSource);

        // Create ImageSourceBuilder with the sources and use original format
        ImageSourceBuilder<BufferedImage> builder = new ImageSourceBuilder<>(sources)
                .useOriginalFormat();

        // Expect HandlingException with specific message
        HandlingException ex = Assert.assertThrows(HandlingException.class,
                builder::obtainSourceImages);

        // Verify the exception message
        String expectedMessage = MessageFormat.format("Multiple available original formats found:[{0}].",
                StringUtils.join(Arrays.asList("jpg", "bmp"), ","));
        Assert.assertEquals(expectedMessage, ex.getMessage());
    }

    // Custom subclass to allow setting original format name
    private static class CustomBufferedImageSource extends ThisBufferedImageSource {
        private String originalFormatName;

        public CustomBufferedImageSource(BufferedImage image) {
            super(image);
        }

        public void setOriginalFormatName(String name) {
            originalFormatName = name;
        }

        @Override
        public String getOriginalFormatName() {
            return originalFormatName;
        }
    }
}

