public class MosaicHandlerTest {

    @Test
    public void test_apply_correctUsage() throws IOException {
        MosaicHandler handler = new MosaicHandler.Builder()
                .sideLength(10)
                .startX(55)
                .startY(35)
                .width(60)
                .height(39)
                .build();
        BufferedImage source = TestUtils.getImageFromResource("input/nothing.jpg");

        BufferedImage target = handler.apply(source);

        // Create expected image as a copy of source
        BufferedImage expected = BufferedImageUtils.copy(source, source.getType());
        Graphics g = expected.getGraphics();

        int currentX = 55;
        while (currentX < 55 + 60) {
            int nextWidth = Math.min(10, 55 + 60 - currentX);
            int currentY = 35;
            while (currentY < 35 + 39) {
                int nextHeight = Math.min(10, 35 + 39 - currentY);

                // Get center RGB from source
                int centerRgb = ColorUtils.obtainRectCenterRGB(source, currentX, currentY, nextWidth, nextHeight);
                g.setColor(ColorUtils.ofRGB(centerRgb));

                // Draw rectangle
                g.fillRect(currentX, currentY, nextWidth, nextHeight);
                currentY += 10;
            }
            currentX += 10;
        }

        g.dispose();

        // Compare target and expected images
        Assert.assertTrue(BufferedImageComparer.isSame(target, expected));
    }

}

