    @Test
    public void testDrawWithinBounds() throws IOException {
        // Create a canvas with sufficient size
        int canvasWidth = 200;
        int canvasHeight = 200;
        BufferedImage source = new BufferedImage(canvasWidth, canvasHeight, BufferedImage.TYPE_INT_RGB);

        // Create a line with valid start and end points
        Line line = new Line.Builder()
                .start(new Point(50, 50))
                .end(new Point(150, 150))
                .build();

        // Create a graphics object for drawing
        Graphics2D g = source.createGraphics();

        // Draw the line
        line.draw(canvasWidth, canvasHeight, g);

        // Create a new image for comparison
        BufferedImage expectedImage = new BufferedImage(canvasWidth, canvasHeight, BufferedImage.TYPE_INT_RGB);
        Graphics2D expectedG = expectedImage.createGraphics();

        // Set the same drawing properties
        expectedG.setColor(Color.BLACK); // Default color if not set
        expectedG.setStroke(new BasicStroke()); // Default stroke if not set

        // Fill the background with white
        expectedG.setColor(Color.WHITE);
        expectedG.fillRect(0, 0, canvasWidth, canvasHeight);

        // Draw the line manually
        expectedG.drawLine(50, 50, 150, 150);

        // Compare the two images by manually checking each pixel
        Assert.assertTrue("The drawn line does not match the expected line.", areImagesEqual(source, expectedImage));

        // Clean up
        g.dispose();
        expectedG.dispose();
    }

    private boolean areImagesEqual(BufferedImage img1, BufferedImage img2) {
        if (img1.getWidth() != img2.getWidth() || img1.getHeight() != img2.getHeight()) {
            return false;
        }

        for (int y = 0; y < img1.getHeight(); y++) {
            for (int x = 0; x < img1.getWidth(); x++) {
                if (img1.getRGB(x, y) != img2.getRGB(x, y)) {
                    return false;
                }
            }
        }
        return true;
    }

}

