package cn.pipe.captor;

import cn.core.ImageGenerator;
import cn.core.tool.Range;
import cn.core.utils.BufferedImageUtils;
import cn.core.utils.ColorUtils;
import org.junit.Before;
import org.junit.Test;
import java.awt.Color;
import java.awt.image.BufferedImage;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.nio.charset.StandardCharsets;

import static org.junit.Assert.assertEquals;

public class HashImageGeneratorTest {

    private HashImageGenerator generator;
    private byte[] testDigest;
    private static final String TEST_CONTENT = "test";
    private static final String ALGORITHM = "SHA-256";
    private static final int GRID_SIZE = 8;
    private static final Color BG_COLOR = Color.WHITE;
    private static final Color FG_COLOR = Color.BLACK;

    @Before
    public void setUp() throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance(ALGORITHM);
        testDigest = digest.digest(TEST_CONTENT.getBytes(StandardCharsets.UTF_8));

        HashImageGenerator.Builder builder = new HashImageGenerator.Builder(testDigest)
                .gridVerticalNum(GRID_SIZE)
                .bgColor(BG_COLOR)
                .fgColor(FG_COLOR);
        generator = builder.build();
    }

    @Test
    public void testGenerateCreatesCorrectImage() throws NoSuchAlgorithmException {
        BufferedImage generatedImage = generator.generate();

        // Verify image dimensions
        int size = GRID_SIZE;
        assertEquals(size, generatedImage.getWidth());
        assertEquals(size, generatedImage.getHeight());

        // Calculate gridHorizontalNum based on GRID_SIZE
        int gridHorizontalNum = (GRID_SIZE + 1) >> 1;

        // Verify each cell's color based on hash digest
        for (int h = 0; h < gridHorizontalNum; h++) {
            for (int v = 0; v < GRID_SIZE; v++) {
                int pos = GRID_SIZE * h + v;
                boolean isForeground = (testDigest[pos] & 1) == 1;

                // Check current cell
                Color expectedColor = isForeground ? FG_COLOR : BG_COLOR;
                assertEquals(expectedColor.getRGB(), generatedImage.getRGB(h, v));

                // Check symmetric cell
                int symmetricH = GRID_SIZE - h - 1;
                assertEquals(expectedColor.getRGB(), generatedImage.getRGB(symmetricH, v));
            }
        }
    }
}

