    @Test
    public void testReturnFirstHandler() {
        // Create test images
        try {
            // Create first image programmatically instead of loading from file
            BufferedImage firstImage = new BufferedImage(200, 300, BufferedImage.TYPE_INT_RGB);
            BufferedImage secondImage = new BufferedImage(200, 300, BufferedImage.TYPE_INT_RGB);
            BufferedImage thirdImage = new BufferedImage(200, 300, BufferedImage.TYPE_INT_RGB);

            List<BufferedImage> inputImages = Arrays.asList(firstImage, secondImage, thirdImage);

            // Create and execute the handler
            AbstractMergeFilter handler = new ReturnFirstHandler();
            List<BufferedImage> result = handler.execute(inputImages);

            // Verify the result
            Assert.assertEquals(1, result.size());
            Assert.assertTrue(isSameImage(result.get(0), firstImage));
        } catch (IOException e) {
            Assert.fail("Failed to load test image: " + e.getMessage());
        }
    }

    private BufferedImage loadImage(String fileName) throws IOException {
        return ImageIO.read(new File(fileName));
    }

    private boolean isSameImage(BufferedImage img1, BufferedImage img2) {
        if (img1.getWidth() != img2.getWidth() || img1.getHeight() != img2.getHeight()) {
            return false;
        }
        for (int x = 0; x < img1.getWidth(); x++) {
            for (int y = 0; y < img1.getHeight(); y++) {
                int rgb1 = img1.getRGB(x, y);
                int rgb2 = img2.getRGB(x, y);
                if (rgb1 != rgb2) {
                    return false;
                }
            }
        }
        return true;
    }
}

