    public void test_mergeWithAutoAdaptAndFiveImages() throws IOException {
        int gridWidth = 56;
        int gridHeight = 36;
        int horizontalNum = 2;
        float alpha = 0.8f;
        Color fillColor = Color.LIGHT_GRAY;

        List<BufferedImage> sources = new ArrayList<>();
