        }

        GridMergeHandler handler = new GridMergeHandler.Builder()
                .gridWidth(gridWidth).gridHeight(gridHeight)
                .horizontalNum(horizontalNum)
                .alpha(alpha).fillColor(fillColor)
                .alignCenter()
                .autoAdapts()
                .build();

        BufferedImage mergedImage = handler.merge(sources);

        // Verify dimensions
        Assert.assertEquals(112, mergedImage.getWidth());
        Assert.assertEquals(108, mergedImage.getHeight());

        // Verify background
