        for (int y = 0; y < expectedBackground.getHeight(); y++) {
            for (int x = 0; x < expectedBackground.getWidth(); x++) {
                int expectedRGB = expectedBackground.getRGB(x, y);
                int actualRGB = mergedImage.getRGB(x, y);
                Assert.assertEquals(expectedRGB, actualRGB);
